import{_ as e,o as a,c as r,a4 as l}from"./chunks/framework.BybBnFXO.js";const c=JSON.parse('{"title":"顶级珠宝工坊","description":"","frontmatter":{"title":"顶级珠宝工坊","gallery":"by-house"},"headers":[],"relativePath":"zh/gallery/by-house.md","filePath":"zh/gallery/by-house.md","lastUpdated":1785925545000}'),o={name:"zh/gallery/by-house.md"};function i(d,t,n,h,s,u){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="顶级珠宝工坊" tabindex="-1">顶级珠宝工坊 <a class="header-anchor" href="#顶级珠宝工坊" aria-label="Permalink to &quot;顶级珠宝工坊&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>七家传奇珠宝工坊——Cartier、Van Cleef &amp; Arpels、Boucheron、Tiffany、 Harry Winston、Graff、Chaumet——各自以独特工艺与美学定义了一个时代。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>Cartier (1847)：Art Deco 雕刻宝石套装、猎豹图腾、Love 手镯。</li><li>Van Cleef &amp; Arpels (1906)：Mystery Set 隐密式镶嵌、Alhambra 四叶草。</li><li>Boucheron (1858)：问号项链、孔雀羽毛系列——自然主义先驱。</li><li>Tiffany &amp; Co. (1837)：六爪镶嵌钻戒开创者、Blue Book 高珠年册。</li><li>Harry Winston (1932)：Cluster 锦簇镶嵌、&quot;钻石之王&quot;。</li><li>Graff (1960)：超大彩钻切割记录（Graff Venus、Lesedi La Rona）。</li><li>Chaumet (1780)：拿破仑宫廷珠宝、Joséphine 皇冠、Liens 连结。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>作品</th><th>详情</th><th>备注</th></tr></thead><tbody><tr><td>Cartier</td><td>Tutti Frutti Bracelet (1928)</td><td>—</td></tr><tr><td>VCA</td><td>Mystery Set Brooch (1933)</td><td>—</td></tr><tr><td>Tiffany</td><td>Six-Prong Engagement (1886)</td><td>—</td></tr></tbody></table><p><em>详见<a href="./intro.html">切割总览</a>。</em></p>',8)])])}const m=e(o,[["render",i]]);export{c as __pageData,m as default};
